MagickBooleanType ReadPSDPixelData(Image *image, size_t channels, size_t row, ssize_t type, const unsigned char *pixels, ExceptionInfo *exception) {
  size_t
    channel,
    count;

  register Quantum
    *q;

  if (image->storage_class == PseudoClass)
    count=image->colors;
  else
    count=image->columns;
  if (pixels == (const unsigned char *) NULL)
    return(MagickFalse);
  if (SetImagePixels(image,0,row,image->columns,1) == (Quantum *) NULL)
    return(MagickFalse);
  q=image->pixels;
  for (channel=0; channel < channels; channel++)
  {
    register ssize_t
      i;

    for (i=0; i < (ssize_t) image->columns; i++)
    {
      switch (type)
      {
        case 0:
        {
          register ssize_t
            byte;

          byte=ConstrainColormapIndex(image,(ssize_t) pixels[i],exception);
          q[channel]=image->colormap[byte].red;
          break;
        }
        case 1:
        {
          register ssize_t
            byte;

          byte=ConstrainColormapIndex(image,(ssize_t) pixels[i],exception);
          q[channel]=image->colormap[byte].green;
          break;
        }
        case 2:
        {
          register ssize_t
            byte;

          byte=ConstrainColormapIndex(image,(ssize_t) pixels[i],exception);
          q[channel]=image->colormap[byte].blue;
          break;
        }
        case 3:
        {
          register ssize_t
            byte;

          byte=ConstrainColormapIndex(image,(ssize_t) pixels[i],exception);
          q[channel]=(Quantum) (ScaleCharToQuantum(pixels[i]) & 0xff);
          break;
        }
        default:
        {
          q[channel]=ScaleCharToQuantum(pixels[i]);
          break;
      }
    }
    pixels+=image->columns;
  }
  SyncImagePixels(image);
  return(MagickTrue);
}

MagickBooleanType ReadPSDPixelData(Image *image, size_t channels, size_t row, ssize_t type, const unsigned char *pixels, ExceptionInfo *exception) {
    register PixelInt *p;
    register ssize_t x;
    size_t depth;
    ssize_t packet_size = 1;

    if ((type == 0) || (type == 4))
        packet_size = image->depth;

    p = GetAuthenticPixels(image, 0, row, image->columns, 1, exception);
    if (p == (PixelInt *) NULL)
        return MagickFalse;

    for (x = 0; x < (ssize_t) image->columns; x++) {
        register ssize_t i;
        for (i = 0; i < (ssize_t) channels; i++) {
            unsigned char value;
            switch (type) {
                case 0:
                case 4:
                    value = *pixels++;
                    break;
                case 3:
                    value = *pixels++;
                    break;
                case 1:
                    value = *pixels++;
                    break;
                case 2:
                    value = *pixels++;
                    break;
                default:
                    value = 0;
                    break;
            }

            if (i < 3) {
                if (i == 0)
                    p[0] = (PixelInt) value;
                else if (i == 1)
                    p[1] = (PixelInt) value;
                else if (i == 2)
                    p[2] = (PixelInt) value;
            }
            else if (i == 3) {
                if (image->alpha_trait != UndefinedPixelTrait)
                    p[3] = (PixelInt) value;
            }
        }
        p += GetPixelChannels(image);
    }

    if (!SyncCacheViewAuthenticPixels(exception))
        return MagickFalse;

    return MagickTrue;
}

MagickBooleanType ReadPSDPixels(Image *image, size_t channels, size_t row, ssize_t type, const unsigned char *pixels, ExceptionInfo *exception) {
    register PixelInt *p;
    size_t q;
    ssize_t packet_size = 1;

    if (image->storage_class == PseudoClass)
        packet_size = image->depth >> 3;
    if ((channels == 4) && (image->alpha_trait != UndefinedAlpha))
        packet_size *= 4;
    else if (channels > 1)
        packet_size *= 3;
    p = (PixelInt *) (image->pixels + row * image->pixels_per_scanline);
    for (q = 0; q < image->columns; q++) {
        switch (type) {
            case 0: {
                register unsigned char *r, *g, *b, *a;
                r = (unsigned char *) pixels;
                g = r + image->columns;
                b = g + image->columns;
                a = b + image->columns;
                p->red = *r++;
                p->green = *g++;
                p->blue = *b++;
                p->alpha = *a++;
                break;
            }
            case 1: {
                register unsigned char *r, *g, *b;
                r = (unsigned char *) pixels;
                g = r + image->columns;
                b = g + image->columns;
                p->red = *r++;
                p->green = *g++;
                p->blue = *b++;
                break;
            }
            case 2: {
                register unsigned char *a;
                a = (unsigned char *) pixels;
                p->alpha = *a++;
                break;
            }
            case 3: {
                register unsigned char *r;
                r = (unsigned char *) pixels;
                p->red = *r++;
                break;
            }
            case 4: {
                register unsigned char *g;
                g = (unsigned char *) pixels;
                p->green = *g++;
                break;
            }
            case 5: {
                register unsigned char *b;
                b = (unsigned char *) pixels;
                p->blue = *b++;
                break;
            }
            default:
                break;
        }
        p++;
    }
    return MagickTrue;
}

