                                  ssize_t type, const unsigned char *pixels,
                                  ExceptionInfo *exception) {
  size_t
    column;

  Quantum
    *q;

  for (column = 0; column < image->columns; column++) {
    register ssize_t
      channel;

    q = GetAuthenticPixels(image, column, row, 1, 1, exception);
    if (q == (Quantum *) NULL)
      return (MagickBooleanType) MagickFalse;
    for (channel = 0; channel < (ssize_t) channels; channel++) {
      ssize_t
        pixel_index;

      pixel_index = (ssize_t) (column * channels + channel);
      switch (type) {
        case 0:
        {
          Quantum
            pixel_value;

          pixel_value = (Quantum) (ScaleCharToQuantum(pixels[pixel_index]));
          SetPixelRed(image,pixel_value,q);
          break;
        }
        case 1:
        {
          Quantum
            pixel_value;

          pixel_value = (Quantum) (ScaleShortToQuantum(*((unsigned short *) &pixels[pixel_index])));
          SetPixelRed(image,pixel_value,q);
          break;
        }
        case 2:
        {
          Quantum
            pixel_value;

          pixel_value = (Quantum) (ScaleLongToQuantum(*((unsigned int *) &pixels[pixel_index])));
          SetPixelRed(image,pixel_value,q);
          break;
        }
        case 3:
        {
          Quantum
            pixel_value;

          pixel_value = (Quantum) (ScaleCharToQuantum(pixels[pixel_index]));
          SetPixelRed(image,pixel_value,q);
          break;
        }
        default:
          break;
      }
    }
    if (!UpdateAuthenticPixels(image,exception))
      return (MagickBooleanType) MagickFalse;
  }
  return (MagickBooleanType) MagickTrue;
}

